mapper.select:
SELECT COUNT(1) > 0
FROM show_info s
JOIN performance_session ps ON ps.show_id = s.id
JOIN ticket_category tc ON tc.session_id = ps.id
WHERE s.id = #{showId}
  AND ps.id = #{sessionId}
  AND tc.id = #{ticketCategoryId}
  AND s.status = 'PUBLISHED'
  AND ps.status = 'PUBLISHED'
  AND tc.status = 'PUBLISHED'
